{"content": "export function parseRange(headerValue) {
  const parts = headerValue.trim().split('=');
  if (parts.length !== 2) {
    throw new Error('Invalid Range header format');
  }

  const rangeUnits = parts[0].trim();
  if (rangeUnits !== 'bytes') {
    throw new Error('Only bytes ranges are supported');
  }

  const rangeValues = parts[1].trim();
  if (rangeValues === '') {
    throw new Error('Invalid range values');
  }

  const ranges = rangeValues.split(',').map(range => {
    const rangeParts = range.trim().split('-');
    if (rangeParts.length !== 2) {
      throw new Error('Invalid range format');
    }

    const start = rangeParts[0] === '' ? 0 : parseInt(rangeParts[0], 10);
    const end = rangeParts[1] === '' ? Number.MAX_SAFE_INTEGER : parseInt(rangeParts[1], 10);

    if (isNaN(start) || isNaN(end)) {
      throw new Error('Invalid range values');
    }

    return { start, end };
  });

  return ranges;
}"}
